mapper.select:
select t.staff_name,t.staff_name staffName,t.tel,t.status_cd,t.status_cd statusCd,t.store_id,t.store_id
storeId,t.admin_flag,t.admin_flag adminFlag,t.store_staff_id,t.store_staff_id storeStaffId,t.staff_id,t.staff_id
staffId,s.create_user_id createUserId,s.address,s.store_type_cd storeTypeCd,s.name,s.tel,s.state
from s_store_staff t
left join s_store s on t.store_id = s.store_id and s.status_cd  = '0'
where 1 =1

    and t.staff_name= #{staffName}


    and t.tel= #{tel}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.admin_flag= #{adminFlag}


    and t.store_staff_id= #{storeStaffId}


    and t.staff_id= #{staffId}

order by t.create_time desc

    limit #{page}, #{row}

